    private const int PageSize = 8;

    [SupplyParameterFromQuery] public int? CategoryId { get; set; }
    [SupplyParameterFromQuery] public string? SearchKeyword { get; set; }
    [SupplyParameterFromQuery] public string? StorageFilter { get; set; }
    [SupplyParameterFromQuery] public string? SortBy { get; set; }
    [SupplyParameterFromQuery] public int? CurrentPage { get; set; }

    private List<Category> _categories = new();
    private List<Product> _products = new();
    private int _page = 1, _totalPages = 1, _totalCount;
    private bool _loading = true;
    private string? _keyword, _storage, _sort;

    protected override async Task OnParametersSetAsync()
    {
        _keyword = SearchKeyword;
        _storage = StorageFilter ?? "";
        _sort = SortBy ?? "";
        await LoadAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender) await Cart.EnsureLoadedAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        await using var db = await DbFactory.CreateDbContextAsync();

        _categories = await db.Categories.Where(c => c.IsActive).OrderBy(c => c.DisplayOrder).ToListAsync();

        var query = db.Products.Include(p => p.Category).Where(p => p.IsActive);

        if (CategoryId is > 0) query = query.Where(p => p.CategoryId == CategoryId);
        if (!string.IsNullOrWhiteSpace(StorageFilter)) query = query.Where(p => p.Storage == StorageFilter);
        if (!string.IsNullOrWhiteSpace(SearchKeyword))
        {
            var kw = SearchKeyword.Trim().ToLower();
            query = query.Where(p => p.Name.ToLower().Contains(kw) ||
                                     p.ModelSeries.ToLower().Contains(kw) ||
                                     p.Color.ToLower().Contains(kw));
        }

        query = SortBy switch
        {
            "price_asc" => query.OrderBy(p => p.Price),
            "price_desc" => query.OrderByDescending(p => p.Price),
            "name" => query.OrderBy(p => p.Name),
            _ => query.OrderByDescending(p => p.Id)
        };

        _totalCount = await query.CountAsync();
        _totalPages = (int)Math.Ceiling(_totalCount / (double)PageSize);
        _page = Math.Max(1, CurrentPage ?? 1);
        if (_page > _totalPages && _totalPages > 0) _page = _totalPages;

        _products = await query.Skip((_page - 1) * PageSize).Take(PageSize).ToListAsync();
        _loading = false;
    }

    private string Url(int? cat = null, int? page = null)
    {
        var categoryId = cat ?? CategoryId;
        return Nav.GetUriWithQueryParameters(Nav.BaseUri, new Dictionary<string, object?>
        {
            ["categoryId"] = categoryId is > 0 ? categoryId : null,
            ["searchKeyword"] = string.IsNullOrWhiteSpace(SearchKeyword) ? null : SearchKeyword,
            ["storageFilter"] = string.IsNullOrWhiteSpace(StorageFilter) ? null : StorageFilter,
            ["sortBy"] = string.IsNullOrWhiteSpace(SortBy) ? null : SortBy,
            ["currentPage"] = page is > 1 ? page : null
        });
    }

    private void ApplyFilter()
    {
        Nav.NavigateTo(Nav.GetUriWithQueryParameters(Nav.BaseUri, new Dictionary<string, object?>
        {
            ["categoryId"] = CategoryId is > 0 ? CategoryId : null,
            ["searchKeyword"] = string.IsNullOrWhiteSpace(_keyword) ? null : _keyword.Trim(),
            ["storageFilter"] = string.IsNullOrWhiteSpace(_storage) ? null : _storage,
            ["sortBy"] = string.IsNullOrWhiteSpace(_sort) ? null : _sort
        }));
    }

    private async Task AddToCart(Product p)
    {
        var result = await Cart.AddToCartAsync(p, 1);
        Toast.Show(result.Message, result.Success ? "success" : "error");
    }

